70	  @Override
71	  public SafeFuture<Void> init() {
72	    return eth1Provider
73	        .getGuaranteedLatestEth1Block()
74	        .thenCompose(
75	            headBlock -> {
76	              if (isOldEnough(headBlock)) {
77	                LOG.trace("Head block is old enough");
78	                waitUntilNextEth1BlockExpected();
79	                return SafeFuture.completedFuture(headBlock);
80	              } else {
81	                LOG.trace("Retrieving block at follow distance");
82	                return getBlock(
83	                    UInt64.valueOf(headBlock.getNumber()).minusMinZero(getEth1FollowDistance()));
84	              }
85	            })
86	        .thenAccept(
87	            block -> {
88	              nextCandidateHead = block;
89	              if (isOldEnough(block)) {
90	                LOG.trace("Init block is old enough");
91	                notifyNewHead(block);
92	              } else if (block.getNumber().equals(BigInteger.ZERO)) {
93	                // Nothing before genesis so wait for it to be old enough then search forwards
94	                LOG.trace("Genesis block is not old enough");
95	                searchForwards = true;
96	                waitForBlockToBeOldEnough(block);
97	              }
98	            });
99	  }
100	
101	  @Override
102	  public SafeFuture<Void> advance() {
103	    checkState(nextCandidateHead != null, "Init has not completed successfully");
104	    if (!searchForwards) {
105	      return searchBackwards();
106	    } else {
107	      return stepForward();
108	    }
109	  }
110	
111	  private SafeFuture<Void> stepForward() {
112	    LOG.trace("Searching forwards from block {}", nextCandidateHead.getNumber());
113	    if (isOldEnough(nextCandidateHead)) {
114	      notifyNewHead(nextCandidateHead);
115	      return eth1Provider
116	          .getEth1Block(UInt64.valueOf(nextCandidateHead.getNumber()).plus(1))
117	          .thenAccept(
118	              maybeBlock ->
119	                  maybeBlock.ifPresentOrElse(
120	                      this::waitForBlockToBeOldEnough, this::waitUntilNextEth1BlockExpected));
121	    }
122	    return SafeFuture.COMPLETE;
123	  }
