126	    LOG.trace(
127	        "Searching backwards from block {} with timestamp {}. Still {}s too recent",
128	        nextCandidateHead::getNumber,
129	        nextCandidateHead::getTimestamp,
130	        () -> UInt64.valueOf(nextCandidateHead.getTimestamp()).minusMinZero(getCutOffTime()));
131	    final UInt64 previousBlockNumber =
